UPDATE `order` SET
status = #{data.status}, refund_amount = #{data.refundAmount}, refund_time = #{data.refundTime}, divide_status = #{data.divideStatus}, divide_amount = #{data.divideAmount}, divide_time = #{data.divideTime},
WHERE id = #{data.id}

UPDATE `order` SET
status = #{data.status}, refund_amount = #{data.refundAmount}, refund_time = #{data.refundTime},
WHERE order_type = #{data.orderType} AND order_id = #{data.orderId}

mapper.select:
SELECT *
FROM `order`
WHERE order_type = #{orderType}
  AND order_id = #{orderId}

SELECT *
FROM `order`

    AND user_id = #{param.searchField1}

        AND `order_type` IN

            #{item}



        AND `status` IN

            #{item}


    AND `status` = #{param.searchIntStatus}
    AND `divide_status` = #{param.searchField2}
    AND `shop_id` = #{param.searchField3}

        AND `order_no` LIKE CONCAT('%', #{param.searchStrField1}, '%')


        AND (phone LIKE CONCAT('%',#{param.keyword},'%') OR nick_name LIKE CONCAT('%',#{param.keyword},'%'))


        AND `pay_time` <= #{param.limitTime}


        AND `create_time` BETWEEN #{param.startTime} AND #{param.endTime}


ORDER BY `id` desc

SELECT COUNT(CASE WHEN `status` IN (1, 2) THEN 1 END) AS orderCount, IFNULL(SUM(CASE WHEN `status` IN (1, 2) THEN amount ELSE 0 END), 0) AS revenue, IFNULL(SUM(CASE WHEN `status` = 2 THEN IFNULL(refund_amount, 0) ELSE 0 END), 0) AS refundAmount FROM `order`
`create_time` BETWEEN #{startTime} AND #{endTime}
AND `status` IN (1, 2)

SELECT e.id AS equipmentId, e.remark AS remark, s.name AS supermarketName, e.serial_number AS serialNumber, IFNULL((SELECT COUNT(*) FROM `order` o2 INNER JOIN `product_order` po2 ON o2.order_no = po2.order_no WHERE po2.equipment_id = e.id AND o2.status = 1
AND o2.create_time BETWEEN #{startTime} AND #{endTime}
), 0) AS orderNum, IFNULL((SELECT COUNT(*) FROM `order` o_pd INNER JOIN `product_order` po_pd ON o_pd.order_no = po_pd.order_no WHERE po_pd.equipment_id = e.id AND po_pd.status = 2
AND o_pd.create_time BETWEEN #{startTime} AND #{endTime}
), 0) AS pendingDeliveryNum, IFNULL((SELECT COUNT(*) FROM `order` o_cp INNER JOIN `product_order` po_cp ON o_cp.order_no = po_cp.order_no WHERE po_cp.equipment_id = e.id AND po_cp.status = 4
AND o_cp.create_time BETWEEN #{startTime} AND #{endTime}
), 0) AS completedNum, IFNULL((SELECT SUM(o3.amount) FROM `order` o3 INNER JOIN `product_order` po3 ON o3.order_no = po3.order_no WHERE po3.equipment_id = e.id AND o3.status = 1
AND o3.create_time BETWEEN #{startTime} AND #{endTime}
), 0) AS orderIncome FROM `equipment` e LEFT JOIN `supermarket_info` s ON e.supermarket_id = s.id WHERE e.status = 1 ORDER BY orderNum DESC

SELECT COUNT(1) AS orderCount, IFNULL(SUM(o.amount), 0) AS revenue, IFNULL(SUM(IFNULL(o.refund_amount, 0)), 0) AS refundAmount FROM `order` o INNER JOIN `product_order` po ON o.order_no = po.order_no
o.create_time BETWEEN #{startTime} AND #{endTime}
AND po.status IN (1, 2, 3, 4, 5, 7)
